
const cds = require ('..')
const LOG = cds.log('serve|bindings',{label:'cds'})
const home = require('os').homedir()
const registry = home + '/.cds/services'
const { execSync:exec } = require ('node:child_process')
const fs = require('node:fs/promises')
const { join } = require('path')

class Bindings {

  services = {}
  servers = {}
  #bound = {}

  then (r,e) {
    const info = ()=> LOG.info ('using bindings from:', { registry: '~'+ registry.slice(home.length) })
    if (cds.watched) cds.prependOnceListener ('connect',info)
    delete Bindings.prototype.then // only once per process
    cds.once('listening', this.export.bind(this))
    return this.import() .then (r,e)
  }


  bind (service, kind) {
    let required = cds.requires [service]
    let binding = this.services [service] || this.services [required?.service]

    if (binding?.endpoints) {

      const server = this.servers [binding.server]

      // If a kind is specified, return a new detached config object
      if (kind) {
        let endpoint = binding.endpoints [kind] || cds.error (`Service ${service} doesn't have an endpoint for ${kind}`)
        return {
          ... !required || required === true ? { ...cds.requires.kinds[kind] } : required,
          kind, credentials: {
            ...required.credentials,
            ...binding.credentials,
            url: server.url + endpoint,
          }
        }
      }

      // Ensure we have a required entry for this binding
      if (!required || required === true) {
        required = cds.requires[service] = { ...cds.requires.kinds[kind] }
      }

      // Determine the kind to use from binding, if not specified
      kind = required.kind = [ required.kind, 'hcql', 'rest', 'odata' ].find (k => k in binding.endpoints)
      || Object.keys(binding.endpoints)[0]

      // Fill in credentials from binding, but do not override existing ones
      Object.assign (required.credentials ??= {}, {
        ...binding.credentials,
        url: server.url + binding.endpoints [kind],
      })

      // REVISIT: temporary fix to inherit kind as well for mocked odata services
      // otherwise mocking with two services does not work for kind:odata-v2
      if (kind === 'odata-v2' || kind === 'odata-v4') required.kind = 'odata'
    }

    return this.#bound [service] = required
  }

  // used by cds.connect
  at (service, _kind) {
    if (_kind) return this.#bound [`${service}:${_kind}`] ??= this.bind (service,_kind)
    return this.#bound [service] ??= this.bind (service, _kind)
  }


  async import() {

    LOG.debug ('reading bindings from:', registry)

    // Fetch all binding files from the registry folder, and get the list of active PIDs in parallel
    const $ = cds.utils.sh, unx = process.platform !== 'win32'
    const ps = unx ? $`ps -o pid=` : $`tasklist /fo csv /nh`
    const [ all, pids ] = await Promise.all([
      // read all files in folder
      fs.readdir(registry) .catch(()=>[]) .then (async all => await Promise.all(all.map (each => {
        if (!each.endsWith('.json')) return; let file = join(registry,each)
        return fs.readFile(file).then(JSON.parse).then(json => ({ file, ...json }))
      }))), //.catch (ignore),
      // fetch active process ids
      async function ps_pids() {
        let pids = (await ps) .map (l => l.trim())
        if (!unx) pids = pids.map (l => l.trim().split(',')[1]?.replace(/"/g,''))
        return pids.reduce ((dd,pid) => (dd[pid]=1, dd), {})
      }() .catch (ignore)
    ])

    // Load all binding files from the registry folder, cleaning up stale ones
    await Promise.all (all.map (each => { try { if (!each) return
      const { file, server, services } = each, id = server.port
      if (server.pid in pids) {
        for (let each in services) this.services[each] = {
          ...services[each],
          server:id
        }
        this.servers[id] = {
          bindings: file.replace(home,'~'),
          ...server
        }
      } else fs.unlink (file) .catch (ignore) // stale server
    } catch { /* ignored */ }}))

    // Fill in loaded bindings to cds.required services
    for (let each in cds.requires)
      this.bind (each)

    return this
  }


  async export() {

    const file = join (registry, cds.server.port+'.json')

    // Binding information about the current server
    const server = this.servers[cds.server.port] = {
      bindings: file.replace(home,'~'),
      root: cds.root.replace(home,'~'),
      url: cds.server.url,
      port: cds.server.port,
      ppid: process.ppid,
      pid: process.pid,
    }
    try {
      server.tty = exec ('tty',{stdio:['inherit']}) .toString().trim()
    } catch { /* ignored */ }

    // Binding information for provided services
    const all = this.services, provided = {}
    for (let srv of cds.service.providers) { if (srv.external) continue
      all[srv.name] = provided[srv.name] = {
        base: server.url,
        endpoints: Object.fromEntries (srv.endpoints.map (ep => [ ep.kind, ep.path ])),
        entities: Object.keys(srv.entities),
        server: cds.server.port
      }
    }

    LOG.debug ('writing bindings to:', file)
    const binding = { server, services: provided }
    await fs.mkdir (registry, { recursive: true })
    await fs.writeFile (file, JSON.stringify(binding,null,2))

    // Clean up the binding file on exit or shutdown
    process.on ('exit', ()=> fs.unlink(file).catch(ignore))
    cds.on ('shutdown', ()=> fs.unlink(file).catch(ignore))
  }

}

const {NODE_ENV} = process.env
if (NODE_ENV === 'test' || global.it || cds.env.no_bindings) {
  Object.defineProperty (module, 'exports', { value: { at: ()=> undefined }})
} else {
  module.exports = new Bindings
}
const ignore = ()=>{}
